import os
import time
from taf.ul.sc.util import util


class SoftwareUpdate:
    """Class for performing eNB software update via EMSSIM"""

    def __init__(self, emssim, emssim_ws, path_to_build_file, remote_dir='/tmp/updates/', activate=True):
        """
        Software update.

        :param emssim: object to ta_moler Emssim class
        :param emssim_ws: object to moler UnixRemote class - server where EMS simulator is launched
        :param path_to_build_file: local/remote path to build file
        :param remote_dir: directory where file will be stored if use method send_update_file_to_emssim_workstation
        :param activate: flag for activation in sw_update command
        """
        self.path_to_build_file = path_to_build_file
        self.emssim = emssim
        self.emssim_ws = emssim_ws
        self.remote_dir = remote_dir
        self.activate = activate
        self.update_start_time = None
        self._time_report = {}

    def download_build_file_to_emssim_workstation(self):
        """
        SCP build file from UnixLocal to EMS workstation.

        :return: None
        """
        util().upload_files(local_dir=os.path.dirname(self.path_to_build_file),
                            local_file=os.path.basename(self.path_to_build_file),
                            remote_dir=self.remote_dir,
                            remote_device_name=self.emssim_ws.name
                            )
        self.path_to_build_file = os.path.join(self.remote_dir, os.path.basename(self.path_to_build_file))

    def software_update(self):
        """
        Perform eNB software update via EMSSIM.

        :return: None
        """
        self.update_start_time = time.time()

        self.emssim.device.run(
            cmd_name="sw_update",
            cmd_params={'target': self.path_to_build_file, 'activate': 1 if self.activate else None})

        self._time_report['update_time'] = time.time() - self.update_start_time
        self._time_report['total'] = self._time_report['update_time']

    def calculate_on_air_wait_time(self):
        """
        Add onAir wait time to time report.

        :return: None
        """
        self._time_report['total'] = time.time() - self.update_start_time
        self._time_report['onAir_time'] = self._time_report['total'] - self._time_report['update_time']

    def get_time_report(self):
        """Return time report.

        :return: Time report
        """
        return self._time_report
